  stop: StopSpec;
  console: ConsoleSpec;
  players: PlayersSpec | null;
  /**
   * Environment for the game and hooks: `GSS_VAR_<KEY>`, `GSS_PORT_<NAME>`, `GSS_SERVER_ID`.
   */
